    readonly 'lifecycle/prepare': LifecycleMethod;
    readonly 'lifecycle/finish': LifecycleMethod;
    readonly 'lifecycle/doctor': LifecycleMethod;
    readonly 'lifecycle/init': LifecycleMethod;
